package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type DateRec struct { // 01 DATE-REC, 12 bytes
	DtId   string // PIC X(4) @0 len=4
	DtYyyy int64  // PIC 9(4) @4 len=4
	DtMm   int64  // PIC 9(2) @8 len=2
	DtDd   int64  // PIC 9(2) @10 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsLeapFlag string = "N" // PIC X len=1 = "N"
var WsQ int64 = 0           // PIC 9(4) len=4 = 0
var WsR4 int64 = 0           // PIC 9(3) len=3 = 0
var WsR100 int64 = 0         // PIC 9(3) len=3 = 0
var WsR400 int64 = 0         // PIC 9(3) len=3 = 0
var WsMaxDay int64 = 0       // PIC 99 len=2 = 0
var WsValid int64 = 0        // PIC 99 len=2 = 0
var WsBadMonth int64 = 0     // PIC 99 len=2 = 0
var WsBadDay int64 = 0       // PIC 99 len=2 = 0

var curRec DateRec
var records []string
var recordIdx int

func pow10(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func storePIC9(v int64, digits int) int64 {
	if digits <= 0 {
		return v
	}
	mod := pow10(digits)
	if v >= 0 {
		return v % mod
	}
	return -((-v) % mod)
}

func formatPIC9(v int64, digits int) string {
	v = storePIC9(v, digits)
	if v < 0 {
		return "-" + fmt.Sprintf("%0*d", digits-1, -v)
	}
	return fmt.Sprintf("%0*d", digits, v)
}

func parseNumericField(s string, digits int) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	v, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		return 0
	}
	return storePIC9(v, digits)
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func isLeap() bool {
	return WsLeapFlag == "Y"
}

func main() {
	_ = decimal.NewFromInt(0)
	MainPara()
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	// read all lines for LINE SEQUENTIAL handling
	scanner := bufio.NewScanner(f)
	records = []string{}
	for scanner.Scan() {
		line := scanner.Text()
		records = append(records, line)
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintf(os.Stderr, "read error: %v\n", err)
		os.Exit(1)
	}
	recordIdx = 0

	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	f.Close()
	out := "VALID: " + formatPIC9(WsValid, 2) + " BAD MONTH: " + formatPIC9(WsBadMonth, 2) + " BAD DAY: " + formatPIC9(WsBadDay, 2)
	fmt.Fprintln(os.Stdout, out)
}

func ReadPara() {
	if recordIdx >= len(records) {
		WsEofFlag = "Y"
		return
	}
	raw := records[recordIdx]
	recordIdx++
	if len(raw) < 12 {
		raw = raw + strings.Repeat(" ", 12-len(raw))
	} else if len(raw) > 12 {
		raw = raw[:12]
	}
	curRec.DtId = raw[0:4]
	curRec.DtYyyy = parseNumericField(raw[4:8], 4)
	curRec.DtMm = parseNumericField(raw[8:10], 2)
	curRec.DtDd = parseNumericField(raw[10:12], 2)
}

func ProcessPara() {
	LeapPara()
	if curRec.DtMm < 1 || curRec.DtMm > 12 {
		WsBadMonth = storePIC9(WsBadMonth+1, 2)
		out := curRec.DtId + " BAD MONTH " + formatPIC9(curRec.DtMm, 2)
		fmt.Fprintln(os.Stdout, out)
	} else {
		DaysPara()
		if curRec.DtDd < 1 || curRec.DtDd > WsMaxDay {
			WsBadDay = storePIC9(WsBadDay+1, 2)
			out := curRec.DtId + " BAD DAY " + formatPIC9(curRec.DtDd, 2) + " MAX " + formatPIC9(WsMaxDay, 2)
			fmt.Fprintln(os.Stdout, out)
		} else {
			WsValid = storePIC9(WsValid+1, 2)
			out := curRec.DtId + " VALID " + formatPIC9(curRec.DtYyyy, 4) + "-" + formatPIC9(curRec.DtMm, 2) + "-" + formatPIC9(curRec.DtDd, 2)
			fmt.Fprintln(os.Stdout, out)
		}
	}
	ReadPara()
}

func LeapPara() {
	q := curRec.DtYyyy / 4
	r := curRec.DtYyyy % 4
	WsQ = storePIC9(q, 4)
	WsR4 = storePIC9(r, 3)

	q = curRec.DtYyyy / 100
	r = curRec.DtYyyy % 100
	WsQ = storePIC9(q, 4)
	WsR100 = storePIC9(r, 3)

	q = curRec.DtYyyy / 400
	r = curRec.DtYyyy % 400
	WsQ = storePIC9(q, 4)
	WsR400 = storePIC9(r, 3)

	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DaysPara() {
	switch curRec.DtMm {
	case 2:
		if isLeap() {
			WsMaxDay = storePIC9(29, 2)
		} else {
			WsMaxDay = storePIC9(28, 2)
		}
	case 4, 6, 9, 11:
		WsMaxDay = storePIC9(30, 2)
	default:
		WsMaxDay = storePIC9(31, 2)
	}
}
